cat > src/pickList.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { buildPickList, OrderFormatError, type StockLot } from "./pickList";

test("format errors name the line", () => {
  const error = new OrderFormatError(7, "quantity must be positive");
  expect(error).toBeInstanceOf(Error);
  expect(error.line).toBe(7);
  expect(error.message).toBe("Line 7: quantity must be positive");
});

const lot = (bin: string, sku: string, qty: number, expires: string | null = null): StockLot => ({
  bin,
  sku,
  qty,
  expires,
});

describe("allocation", () => {
  test("empty orders text gives an empty pick list", () => {
    expect(buildPickList("", [])).toEqual({ picks: [], shortages: [] });
  });
});
EOF
bun test 2>&1 | grep -E "pass|fail"
